[metadata] {"type": "create", "filePath": "/workspace/repo/server/services/zigbee2mqtt/lib/reset.js", "content": "const fs = require('fs/promises');
const path = require('path');

const logger = require('../../../utils/logger');
const { CONFIGURATION } = require('./constants');

/**
 * @description Reset the Zigbee2mqtt integration to a clean factory state.
 * @returns {Promise<void>} Resolves once the integration has been reset.
 * @example
 * await this.reset();
 */
async function reset() {
  logger.info('Zigbee2mqtt: resetting integration to factory state...');

  // Stop & remove both the MQTT and zigbee2mqtt containers
  await this.disconnect();

  // Destroy all configuration variables
  const variablesToDestroy = [
    CONFIGURATION.Z2M_DRIVER_PATH,
    CONFIGURATION.Z2M_BACKUP,
    CONFIGURATION.ZIGBEE_DONGLE_NAME,
    CONFIGURATION.Z2M_MQTT_MODE,
    CONFIGURATION.Z2M_TCP_PORT,
    CONFIGURATION.MQTT_URL_KEY,
    CONFIGURATION.Z2M_MQTT_USERNAME_KEY,
    CONFIGURATION.Z2M_MQTT_PASSWORD_KEY,
    CONFIGURATION.GLADYS_MQTT_USERNAME_KEY,
    CONFIGURATION.GLADYS_MQTT_PASSWORD_KEY,
    CONFIGURATION.DOCKER_MQTT_VERSION,
    CONFIGURATION.DOCKER_Z2M_VERSION,
  ];

  await Promise.all(variablesToDestroy.map((key) => this.gladys.variable.destroy(key, this.serviceId)));

  // Delete the zigbee2mqtt data folder
  const { basePathOnContainer } = await this.gladys.system.getGladysBasePath();
  const zigbee2mqttFolder = path.join(basePathOnContainer, 'zigbee2mqtt');
  await fs.rm(zigbee2mqttFolder, { recursive: true, force: true });

  // Reset in-memory state
  this.discoveredDevices = {};
  this.topicBinds = {};
  this.usbConfigured = false;
  this.mqttExist = false;
  this.mqttRunning = false;
  this.mqttContainerRunning = false;
  this.zigbee2mqttExist = false;
  this.zigbee2mqttRunning = false;
  this.gladysConnected = false;
  this.zigbee2mqttConnected = false;
  this.z2mPermitJoin = false;
  this.coordinatorFirmware = null;
  this.z2mContainerError = null;

  this.emitStatusEvent();

  // Disconnect from MQTT broker if still connected
  if (this.mqttClient) {
    this.mqttClient.end();
    this.mqttClient.removeAllListeners();
    this.mqttClient = null;
  }

  // Cancel the recurrent backup job
  if (this.backupScheduledJob) {
    this.backupScheduledJob.cancel();
  }

  logger.info('Zigbee2mqtt: integration reset complete.');
}

module.exports = {
  reset,
};
